package local.tvmorph.tv;
import android.app.*;import android.webkit.*;import android.widget.*;import android.view.*;
/** OS WebView embed. It has no JavaScript bridge and leaves the detail page intact. */
final class TrailerDialog{
 static void open(Activity owner,String value){if(value==null||!value.matches("[A-Za-z0-9_-]{11}")){new AlertDialog.Builder(owner).setMessage(UiSettings.text(owner,"المزوّد لم يوفّر رابط تريلر مباشر لهذا العنوان.","The provider has not supplied a direct trailer for this title.")).setPositiveButton(UiSettings.text(owner,"إغلاق","Close"),null).show();return;}Dialog dialog=new Dialog(owner){@Override public boolean dispatchKeyEvent(KeyEvent event){int code=event.getKeyCode();if(code==KeyEvent.KEYCODE_BACK||code==KeyEvent.KEYCODE_ESCAPE){if(event.getAction()==KeyEvent.ACTION_UP&&!event.isCanceled())dismiss();return true;}return super.dispatchKeyEvent(event);}@Override public void onBackPressed(){dismiss();}};dialog.setCancelable(true);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setBackgroundColor(0xff101c35);Button close=new Button(owner);close.setText(UiSettings.text(owner,"إغلاق التريلر","Close trailer"));close.setTextColor(0xffffffff);box.addView(close,new LinearLayout.LayoutParams(-1,Math.round(48*owner.getResources().getDisplayMetrics().density)));WebView video=new WebView(owner);video.setBackgroundColor(0xff101c35);video.getSettings().setJavaScriptEnabled(true);video.getSettings().setMediaPlaybackRequiresUserGesture(false);video.getSettings().setAllowFileAccess(false);video.getSettings().setAllowContentAccess(false);video.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);video.setWebChromeClient(new WebChromeClient());video.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return r.isForMainFrame();}@Override public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();}});box.addView(video,new LinearLayout.LayoutParams(-1,0,1));dialog.setContentView(box);close.setOnClickListener(v->dialog.dismiss());dialog.setOnDismissListener(d->{video.stopLoading();video.loadUrl("about:blank");video.destroy();});dialog.show();dialog.getWindow().setLayout((int)(owner.getResources().getDisplayMetrics().widthPixels*.9f),(int)(owner.getResources().getDisplayMetrics().heightPixels*.84f));String origin="https://"+owner.getPackageName()+"/";String html="<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='referrer' content='strict-origin-when-cross-origin'><style>html,body,iframe{width:100%;height:100%;margin:0;border:0;background:#101c35}</style></head><body><iframe referrerpolicy='strict-origin-when-cross-origin' src='https://www.youtube.com/embed/"+value+"?autoplay=1&amp;playsinline=1' allow='autoplay; encrypted-media; fullscreen' allowfullscreen></iframe></body></html>";video.loadDataWithBaseURL(origin,html,"text/html","UTF-8",null);close.requestFocus();}
}
